class Sbts(object):
    def __init__(self, driver, download_checker, screenshot_dir):
        self._driver = driver
        self._download_checker = download_checker
        self._login_page = None
        self._logout_page = None
        self._lab_access_login = LabAccessLoginPage(self._driver)
        self._debug = Debug(self._driver, screenshot_dir)
        self._user_account_management_for_admin = UserAccountManagementForNemuadmin(self._driver)
        self._bts_basic_info = BtsBasicInfo(self._driver)
        self._bts_status = BtsStatus(self._driver)
        self._bts_start_up_view_modal = BtsStartUpViewModal(self._driver)
        self._configuration = Configuration(self._driver, download_checker, screenshot_dir)
        self._performance = Performance(self._driver, download_checker)
        self._alarms = Alarms(self._driver, download_checker)
        self._software = Software(self._driver, download_checker)
        self._web_element_manager_reload_modal = WebElementManagerReloadModal(self._driver)
        self._plug_and_play_modal = PlugAndPlayModal(self._driver)
        self._diagnostic = Diagnostic(self._driver, download_checker)
        self._procedures = Procedures(self._driver)
        self._rnd_mode = RndMode(self._driver, download_checker)
        self._options = Options(self._driver)
        self._browser = Browser(self._driver)

    @property
    def download_checker(self):
        return self._download_checker

    @property
    def debug(self):
        return self._debug

    @property
    def lab_access_login(self):
        return self._lab_access_login

    @property
    def login_page(self):
        return self._login_page

    @property
    def logout_page(self):
        return self._logout_page

    @property
    def user_account_management_for_admin(self):
        return self._user_account_management_for_admin

    @property
    def bts_basic_info(self):
        return self._bts_basic_info

    @property
    def bts_status(self):
        return self._bts_status

    @property
    def bts_start_up_view_modal(self):
        return self._bts_start_up_view_modal

    @property
    def configuration(self):
        return self._configuration

    @property
    def performance(self):
        return self._performance

    @property
    def alarms(self):
        return self._alarms

    @property
    def software(self):
        return self._software

    @property
    def web_element_manager_reload_modal(self):
        return self._web_element_manager_reload_modal

    @property
    def plug_and_play_modal(self):
        return self._plug_and_play_modal

    @property
    def diagnostic(self):
        return self._diagnostic

    @property
    def procedures(self):
        return self._procedures

    @property
    def rnd_mode(self):
        return self._rnd_mode

    @property
    def options(self):
        return self._options

    @property
    def browser(self):
        return self._browser

    def login(self, url, username, password, download_checker, screenshot_dir=None,
              wait_session_modal_timeout=10, port=443, ssl=True, timeout=60,
              modal_action_configurations=None, readonly=False):
        self._download_checker = download_checker
        self._login_page = SbtsLoginPage(self._driver, screenshot_dir)
        return self._login_page.login(url,
                                      username,
                                      password,
                                      int(wait_session_modal_timeout),
                                      port,
                                      ssl,
                                      int(timeout),
                                      modal_action_configurations=modal_action_configurations,
                                      readonly=bool(readonly))

    def login_with_offline_mode(self, file_path, download_checker, screenshot_dir=None):
        self._download_checker = download_checker
        self._login_page = SbtsLoginPage(self._driver, screenshot_dir)
        self._login_page.login_with_offline_mode(file_path)

    def login_after_screen_lock(self, passwd, timeout):
        self._login_page.login_after_screen_lock(passwd, timeout)

    def logout(self, click_timeout, timeout):
        self._logout_page = LogoutPage(self._driver)
        self._logout_page.logout(click_timeout, timeout)


