    def __init__(self, driver, download_checker, screenshot_dir):
        super(Sbts20B, self).__init__(driver, download_checker, screenshot_dir)
        self._software = v20b.Software(self._driver, download_checker)
        self._diagnostic = v20b.Diagnostic(driver, self.download_checker)
        self._rnd_mode = v20b.RndMode(driver, self.download_checker)


